// Take top 40 by PnL, keep only what we need
const traders = $input.all()
  .map(i => i.json)
  .filter(t => t.proxyWallet && t.pnl > 0)
  .slice(0, 40)
  .map(t => ({ json: {
    proxyWallet: t.proxyWallet,
    userName: t.userName || t.proxyWallet.slice(0, 8),
    rank: t.rank,
    pnl: t.pnl,
    vol: t.vol,
    verified: t.verifiedBadge === true
  }}));
return traders;

// Keep only BUY trades from the last 48h — positions are stale, fresh entries are the signal
const cutoff = Date.now() - 48 * 3600 * 1000;
const out = [];
for (const it of $input.all()) {
  const t = it.json;
  if (!t || t.side !== 'BUY') continue;
  if (!t.conditionId || !t.asset) continue;
  if (t.timestamp * 1000 < cutoff) continue;
  out.push({ json: {
    wallet: t.proxyWallet,
    traderName: t.name || t.proxyWallet.slice(0, 8),
    asset: t.asset,
    conditionId: t.conditionId,
    outcome: t.outcome,
    title: t.title,
    slug: t.slug,
    eventSlug: t.eventSlug,
    shares: t.size,
    price: t.price,
    usd: Math.round(t.size * t.price),
    ts: t.timestamp
  }});
}
return out;

// Group fresh BUYs by token; count distinct top MONTH-PNL traders per outcome
// (verifiedBadge is false for all top-50 traders — identity filters unusable; quality comes from size/freshness/settle/drift gates downstream)
const buys = $input.all().map(i => i.json);
const groups = new Map();
for (const b of buys) {
  if (!groups.has(b.asset)) {
    groups.set(b.asset, {
      asset: b.asset,
      conditionId: b.conditionId,
      outcome: b.outcome,
      title: b.title,
      slug: b.slug,
      eventSlug: b.eventSlug,
      wallets: new Map(),
      totalUsd: 0,
      priceSum: 0,
      weightedPriceSum: 0,
      totalShares: 0,
      count: 0,
      lastTs: 0
    });
  }
  const g = groups.get(b.asset);
  g.wallets.set(b.wallet, b.traderName);
  g.totalUsd += b.usd;
  g.priceSum += b.price;
  g.weightedPriceSum += b.price * (b.shares || 0);
  g.totalShares += (b.shares || 0);
  g.count++;
  g.lastTs = Math.max(g.lastTs, b.ts);
}
const MIN_TRADERS = 3; // consensus threshold
const picks = [...groups.values()]
  .filter(g => g.wallets.size >= MIN_TRADERS)
  .map(g => ({
    asset: g.asset,
    conditionId: g.conditionId,
    outcome: g.outcome,
    title: g.title,
    slug: g.slug,
    eventSlug: g.eventSlug,
    skip: false,
    traderCount: g.wallets.size,
    traderNames: [...g.wallets.entries()].map(([w, n]) => n || w.slice(0, 8)),
    totalUsd: Math.round(g.totalUsd),
    avgEntryPrice: g.totalShares > 0 ? +(g.weightedPriceSum / g.totalShares).toFixed(3) : +(g.priceSum / g.count).toFixed(3),
    lastEntryTs: g.lastTs
  }))
  .sort((a, b) => b.traderCount - a.traderCount || b.totalUsd - a.totalUsd);
// Always emit at least one item so the router node always executes
if (picks.length === 0) {
  return [{ json: { skip: true, message: 'No strong smart-money consensus found in the last 48h.' } }];
}
return picks.map(p => ({ json: p }));

// Group picks by EVENT: trades API eventSlug is inconsistent (slug OR numeric id).
// Numeric ids -> resolve via the market slug (sports market slug == event slug).
const picks = $input.all().map(i => i.json).filter(p => p.skip !== true && (p.eventSlug || p.slug));
const byEvent = new Map();
for (const p of picks) {
  const key = /^\d+$/.test(String(p.eventSlug)) ? p.slug : p.eventSlug;
  if (!key) continue;
  if (!byEvent.has(key)) byEvent.set(key, []);
  byEvent.get(key).push(p);
}
if (byEvent.size === 0) return [];
return [...byEvent.keys()].map(s => ({ json: { eventSlug: s } }));

// Verification: match picks to gamma event markets by slug (fallback: clob token id)
const all = $input.all().map(i => i.json);
const picks = all.filter(x => x.asset);
const events = all.filter(x => Array.isArray(x.markets));
const out = [];
for (const p of picks) {
  const ev = events.find(e => e.slug === p.eventSlug);
  if (!ev) continue;
  const mkts = ev.markets || [];
  let m = mkts.find(x => x.slug === p.slug);
  if (!m) m = mkts.find(x => (x.clobTokenIds || '').split(',').map(s => s.replace(/[\[\]"]/g, '')).includes(String(p.asset)));
  if (!m) continue;
  const liq = parseFloat(m.liquidity || '0') || 0;
  if (m.closed === true || m.active === false || liq < 5000) continue;
  const endMs = m.endDate ? new Date(m.endDate).getTime() : null;
  const settleDays = endMs ? Math.ceil((endMs - Date.now()) / 86400000) : null;
  // F3 fix: settleDays <= 0 = market already settled/ended — reject, was passing before
  if (settleDays !== null && (settleDays <= 0 || settleDays > 7)) continue; // no settled markets, no long holds
  let outcomes = [], prices = [];
  try { outcomes = JSON.parse(m.outcomes || '[]'); } catch (e) {}
  try { prices = (JSON.parse(m.outcomePrices || '[]')).map(x => parseFloat(x)); } catch (e) {}
  const idx = outcomes.indexOf(p.outcome);
  const curPrice = idx >= 0 && prices[idx] !== undefined ? prices[idx] : null;
  out.push({ json: {
    ...p,
    marketQuestion: m.question,
    liquidity: Math.round(liq),
    currentPrice: curPrice,
    edge: curPrice !== null ? +(curPrice - p.avgEntryPrice).toFixed(3) : null,
    marketUrl: `https://polymarket.com/event/${ev.slug}`,
    endDate: m.endDate,
    settleDays
  }});
}
// If the input was already a no-picks skip, emit nothing (router already posted the notice)
if (picks.length === 0) {
  return all.some(x => x.skip === true) ? [] : [{ json: { skip: true, message: 'Consensus found but no tradeable markets (closed or too thin).' } }];
}
if (out.length === 0) {
  return [{ json: { skip: true, message: 'Consensus found but no tradeable markets (closed or too thin).' } }];
}
return out;

// US Availability Gate (HERMES-009): the user trades on the CFTC-regulated US exchange,
// so a signal is only actionable if the market is listed on polymarket.us. Verify each
// pick's event on gateway.polymarket.us and rewrite links to the .us domain.
const picks = $input.all().map(i => i.json);
if (picks[0] && picks[0].skip === true) {
  return [{ json: picks[0] }];
}
const API = 'https://gateway.polymarket.us/v1/events?slug=';
const TIMEOUT_MS = 8000;

async function check(p) {
  // n8n Code-node sandbox has neither fetch nor AbortController; helpers are exposed as plain `helpers` (no $).
  // Use helpers.httpRequest + Promise.race timeout.
  const timeout = new Promise((_, rej) => setTimeout(() => rej(new Error('gateway timeout')), TIMEOUT_MS));
  try {
    const res = await Promise.race([
      helpers.httpRequest({
        method: 'GET',
        url: API + encodeURIComponent(p.eventSlug || p.slug || ''),
        headers: { 'User-Agent': 'polymarket-consensus-scanner/1.0' },
        json: true
      }),
      timeout
    ]);
    let data = res && res.data;
    if (typeof data === 'string') {
      try { data = JSON.parse(data); } catch (e) { data = {}; }
    }
    const ev = (data && data.events || [])[0];
    if (!ev) {
      return { ...p, usAvailable: false, usReason: 'not listed on Polymarket US' };
    }
    const numMarkets = ev.marketCounts && ev.marketCounts.numMarkets != null ? ev.marketCounts.numMarkets : ((ev.markets || []).length);
    if (ev.closed === true || numMarkets === 0) {
      return { ...p, usAvailable: false, usReason: 'closed on Polymarket US' };
    }
    return { ...p, usAvailable: true, usReason: null, marketUrl: 'https://polymarket.us/event/' + ev.slug, usTitle: ev.title };
  } catch (err) {
    const msg = String((err && (err.message || err.error)) || err);
    return { ...p, usAvailable: false, usReason: 'gateway error (' + msg.slice(0, 60) + ')' };
  }
}

const run = async () => {
  const results = await Promise.all(picks.map(check));
  const ok = results.filter(r => r.usAvailable);
  const dropped = results.filter(r => !r.usAvailable);
  let note = null;
  if (dropped.length > 0) {
    const names = dropped.map(x => String(x.title || '?')).map(t => t.length > 38 ? t.slice(0, 36) + '…' : t);
    note = '⚠️ ' + dropped.length + ' signal' + (dropped.length > 1 ? 's' : '') + ' not available on Polymarket US'
      + (dropped.length <= 6 ? ' (' + names.join('; ') + ')' : '') + ' — excluded.';
  }
  if (ok.length === 0) {
    return [{ json: { skip: true, message: 'Signals found but none are available on Polymarket US (' + (dropped[0] ? dropped[0].usReason : 'check failed') + ').' } }];
  }
  return ok.map(p => ({ json: { ...p, usNote: note } }));
};
return run();

// Build the copy-trading signal prompt: is it still early enough to follow smart money?
const inputItems = $input.all().map(i => i.json);
if (inputItems[0] && inputItems[0].skip === true) {
  return [{ json: { skip: true, message: inputItems[0].message || 'No tradeable picks.' } }];
}
const bankroll = $('Bankroll Parse').first().json.bankroll;
// Noise pre-filter (HERMES-007 F4): only >= $10k smart-money volume reaches the report
const picks = inputItems.filter(p => (p.totalUsd || 0) >= 10000).slice(0, 10);
if (!picks.length) {
  return [{ json: { skip: true, message: 'No signals above $10k smart-money this run.' } }];
}
const nowS = Date.now() / 1000;
const compact = picks.map((p, i) => {
  const drift = (p.avgEntryPrice > 0 && p.currentPrice != null) ? ((p.currentPrice - p.avgEntryPrice) / p.avgEntryPrice * 100) : null;
  return {
    id: i,
    market: p.title,
    candidate_side: p.outcome,
    entry_price: p.avgEntryPrice,
    current_price: p.currentPrice,
    drift_pct: drift != null ? +drift.toFixed(1) : null,
    hours_ago: p.lastEntryTs ? Math.max(0, Math.round((nowS - p.lastEntryTs) / 3600)) : null,
    smart_money_usd: p.totalUsd,
    traders: p.traderCount,
    liquidity: p.liquidity,
    settles_in_days: p.settleDays,
    url: p.marketUrl,
    slug: p.slug,
    asset: String(p.asset)
  };
});
const promptText = `You are a Polymarket copy-trading signal analyst. Polymarket is largely efficient — we do not try to beat the market. The play: when several top traders buy the same side within 48h, follow them EARLY and ride the move (their continued buying and information advantage push the price). Your job per pick: say whether it is still worth copying NOW.

For EACH pick output:
- "side": the exact outcome name from candidate_side (e.g. 'Yes', 'G2', 'Over' — do NOT force YES/NO for sports markets)
- "price": current price as number
- "prob": your honest estimate (0-1) of the probability this side wins/profits. If the smart-money signal is strong and fresh, prob may exceed price even though the market is fair overall.
- "reason": one short line, max 12 words: the strongest reason to copy NOW or NOT (e.g. "fresh 5-trader buy, price flat" / "already ran +18%, late" / "thin book").

Rules:
- These markets all settle within 7 days — we ride the move, we do not hold to settlement. prob is your honest estimate of the probability the side wins or drifts profitably in the next few days, using the smart-money signal as evidence — do NOT simply mirror the market price. A fresh multi-trader consensus near their entry price is a real signal.
- If the price already ran far from their entry, prob should be close to price (edge gone) and say so in the reason.
- If drift is negative (price BELOW their entry), that is a better copy entry — say so.
- Be terse. Never mention hedging, gambling warnings, or "the market is mispriced".

DATA:
${JSON.stringify(compact, null, 1)}

Reply with ONLY a JSON block (no markdown outside it):
{
  "picks": [
    {"id": index_from_data, "market": "...", "side": "exact outcome name from candidate_side", "price": current_price_as_number, "prob": probability_0_to_1_that_this_side_wins, "reason": "one short line, max 12 words"}
  ]
}
Include every pick from DATA; set prob at or below price when there is no copy value left.`;
// HERMES-009: carry the US-availability exclusion note into the report
return [{ json: { skip: false, promptText, picks: compact, usNote: inputItems[0] && inputItems[0].usNote ? inputItems[0].usNote : null } }];

// Copy-trading verdicts: RULE-BASED on consensus strength + drift; Kelly sized on a conviction premium
const claude = $input.first().json;
const text = (claude.content || []).map(c => c.text || '').join('\n');
const bankroll = $('Bankroll Parse').first().json.bankroll;
const dateStr = new Date().toISOString().slice(0, 10);

const dataPicks = $('Prompt & Route').first().json.picks || [];
const byId = new Map(dataPicks.map((p, i) => [parseInt(p.id, 10), p]));

// Discord ping/markdown sanitizer
const clean = s => String(s || '')
  .replace(/@(everyone|here)/g, '@\u200b$1')
  .replace(/<@!?&?\d+>/g, '')
  .replace(/<#\d+>/g, '')
  .replace(/<a?:\w+:\d+>/g, '')
  .replace(/\|\|/g, '')
  .trim();
const trunc = (s, n) => { const a = Array.from(s); return a.length <= n ? s : a.slice(0, n).join(''); };

let picks = [];
const m = text.match(/```json\s*([\s\S]*?)(```|$)/);
if (m) { try { picks = (JSON.parse(m[1]).picks) || []; } catch (e) {} }
else { try { picks = JSON.parse(text).picks || []; } catch (e) {} }

if (!picks.length) {
  const esc = clean(text);
  return [{ json: { reportText: trunc('**Polymarket Smart Money Copy Signals — ' + dateStr + '**\n(no structured picks — raw analysis)\n\n' + esc, 1900), dateStr } }];
}

// Build verdicts with rule-based sizing
const entries = [];
for (const p of picks.slice(0, 15)) {
  const dp = byId.get(parseInt(p.id, 10)) || {};
  const price = parseFloat(p.price);
  const side = clean(String(p.side || '?')).toUpperCase().substring(0, 20);
  const reason = clean(p.reason);
  const traders = parseInt(dp.traders, 10) || 0;
  const usd = dp.smart_money_usd || 0;
  const hoursAgo = dp.hours_ago != null ? parseInt(dp.hours_ago, 10) : null;
  const settleDays = dp.settles_in_days != null ? parseInt(dp.settles_in_days, 10) : null;
  const drift = dp.drift_pct != null ? parseFloat(dp.drift_pct) : null;

  let verdict = null;
  let stake = 0;
  let shares = 0;
  // RULE: fresh consensus (>=3 top traders) + price still within +10% of their entry = copy signal
  if (!(price > 0.01 && price < 0.999)) {
    verdict = '🚫 SKIP — invalid price';
  } else if (usd < 10000) {
    verdict = '🚫 SKIP — small signal (<$10k smart money)';
  } else if (price >= 0.99) {
    verdict = '👀 WATCH — at ceiling, no profit room';
  } else if (traders >= 3 && drift !== null && drift >= -30 && drift <= 6 && (hoursAgo === null || hoursAgo <= 24)) {
    const premium = Math.min(0.08, 0.04 + 0.01 * Math.max(0, traders - 3) + (drift <= 0 ? 0.01 : 0));
    const qEff = Math.min(0.99, Math.max(0.02, price + premium));
    const kelly = (qEff - price) / (1 - price);
    stake = Math.min(0.5 * kelly * bankroll, 0.15 * bankroll);
    shares = Math.floor(stake / price);
    verdict = '👉 COPY — bet the ' + side + ' side @ ' + price.toFixed(3) + ' — stake $' + stake.toFixed(2) + ' (~' + shares + ' sh)';
  } else if (drift !== null && drift <= 15 && drift >= -30) {
    verdict = '👀 WATCH — ran +' + drift.toFixed(0) + '% from entry';
  } else {
    verdict = '🚫 SKIP — ran ' + (drift !== null ? '+' + drift.toFixed(0) + '%' : 'too far') + ' from entry';
  }
  const driftTxt = drift !== null ? 'entry ' + (dp.entry_price || 0).toFixed(3) + (drift >= 0 ? ', +' : ', ') + drift.toFixed(1) + '%' : '';
  const usdTxt = usd ? ' · $' + (usd >= 1e6 ? (usd / 1e6).toFixed(2) + 'M' : usd >= 1000 ? (usd / 1000).toFixed(1) + 'k' : usd.toFixed(0)) : '';
  const settleTxt = settleDays !== null ? (settleDays <= 0 ? ' · settles today' : ' · settles in ' + settleDays + 'd') : '';
  const stats = traders + ' traders' + usdTxt + (hoursAgo != null ? ' · ' + hoursAgo + 'h ago' : '') + (driftTxt ? ' · ' + driftTxt : '') + settleTxt;
  const url = dp.url || '';
  const mkt = clean(String(p.market || '?')).substring(0, 90);
  // HERMES-008: append the exact market URL so manual execution matches the right market (same-name mixups)
  entries.push({ verdict, stake, line: '**' + mkt + '**' + (url ? ' — ' + url : '') + '\n' + verdict + '\n' + stats + '\n' + reason });
}

// Cap TOTAL exposure at 25% of bankroll (scale stakes down proportionally)
const total = entries.reduce((s, e) => s + e.stake, 0);
const cap = 0.25 * bankroll;
if (total > cap && total > 0) {
  const scale = cap / total;
  for (const e of entries) {
    e.stake *= scale;
    const priceMatch = e.line.match(/@ (\d+\.\d+) — stake \$([\d.]+) \((\d+) sh\)/);
    if (priceMatch) {
      const price = parseFloat(priceMatch[1]);
      const newShares = Math.floor(e.stake / price);
      e.line = e.line.replace(/stake \$[\d.]+ \(\d+ sh\)/, 'stake $' + e.stake.toFixed(2) + ' (' + newShares + ' sh)');
    }
  }
}
const totalExposure = entries.reduce((s, e) => s + e.stake, 0);
const actionable = entries.filter(e => e.verdict.includes('COPY') || e.verdict.includes('WATCH'));
const shown = (actionable.length > 0 ? actionable : entries).slice(0, 8).map(e => e.line).join('\n\n');

let out = '**Polymarket Smart Money Copy Signals — ' + dateStr + '**\n**Bankroll: $' + bankroll.toFixed(2) + '**\n_Exit plan: take profit at +15% or before settlement · cut at -20% from entry_\n\n';
  // HERMES-009: surface markets excluded for US availability
  const usNote = $('Prompt & Route').first().json.usNote;
  if (usNote) out += usNote + '\n\n';

if (shown) out += shown + '\n\n';
if (actionable.length === 0) out += '_No copy signals — consensus stale or already repriced._\n';
out += '**Total suggested exposure: $' + totalExposure.toFixed(2) + ' (' + Math.round(100 * totalExposure / bankroll) + '% of bankroll)**';
return [{ json: { reportText: trunc(out, 1950), dateStr } }];

// Parse bankroll from the file output; default $100
const raw = $input.all().map(i => i.json).map(j => j.stdout || JSON.stringify(j)).join(' ') || '100';
const m = raw.match(/(\d+(\.\d+)?)/);
let bankroll = m ? parseFloat(m[1]) : 100;
if (!isFinite(bankroll) || bankroll <= 0) bankroll = 100;
return [{ json: { bankroll: Math.round(bankroll * 100) / 100 } }];

// Hardening: only allow manual triggers with the shared secret header
const h = $json.headers || {};
const key = h['x-consensus-key'] || h['X-Consensus-Key'];
if (key !== 'k3lly-0de036abc799e947') {
  throw new Error('Unauthorized: missing/invalid x-consensus-key header');
}
return $input.all();
